# Doane's rule for the bins of a series without recorded edges, derived here: k = 1 + log2(n) + log2(1 + |g1| / sigma),
# g1 the moment skewness and sigma = sqrt(6 (n - 2) / ((n + 1) (n + 3))) its standard error under normality, rounded;
# StatsDirect takes the skewness as 0 for n <= 3 or equal values. The edges divide the range into k equal bins.
doane <- function(x) {
  if (length(x) <= 3 || var(x) == 0) return(round(1 + log2(length(x))))
  m2 <- mean((x - mean(x))^2)
  m3 <- mean((x - mean(x))^3)
  sigma <- sqrt(6 * (length(x) - 2) / ((length(x) + 1) * (length(x) + 3)))
  round(1 + log2(length(x)) + log2(1 + abs(m3 / m2^1.5) / sigma))
}
emit(seq(min(igm), max(igm), length.out = doane(igm) + 1))
